import json
import re

from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema import Message


class MiraMilestoneJSONValidator(Component):
    display_name = "Mira Milestone JSON Validator"
    description = "Validates milestone reports against source data."
    icon = "shield-check"

    inputs = [
        MessageTextInput(
            name="model_response",
            display_name="Model Response",
            required=True,
        ),
        MessageTextInput(
            name="milestone_context",
            display_name="Milestone Context",
            required=True,
        ),
        MessageTextInput(
            name="user_request",
            display_name="User Request",
            required=True,
        ),
    ]

    outputs = [
        Output(
            name="validated_response",
            display_name="Validated Response",
            method="validate_json",
        )
    ]

    def validate_json(self) -> Message:
        errors = []

        def parse_json(value, label):
            try:
                if hasattr(value, "text"):
                    value = value.text
                if isinstance(value, dict):
                    return value
                raw = str(value or "").strip()
                raw = re.sub(r"^```(?:json)?\s*", "", raw)
                raw = re.sub(r"\s*```$", "", raw)
                parsed = json.loads(raw)
                if not isinstance(parsed, dict):
                    raise ValueError("Expected a JSON object")
                return parsed
            except Exception as exc:
                errors.append(f"{label} is invalid JSON: {exc}")
                return {}

        source = parse_json(
            self.milestone_context, "Milestone context"
        )
        result = parse_json(
            self.model_response, "Model response"
        )

        request = (
            self.user_request.text
            if hasattr(self.user_request, "text")
            else str(self.user_request or "")
        )

        required_fields = [
            "status",
            "report_type",
            "project_name",
            "report_scope",
            "executive_summary",
            "total_source_phases",
            "planned_project_duration_weeks",
            "phases",
            "schedule_risks",
            "recommendations",
            "data_quality_notes",
            "missing_information",
            "sources_used",
        ]

        for field in required_fields:
            if field not in result:
                errors.append(f"Missing required field: {field}")

        list_fields = [
            "phases",
            "schedule_risks",
            "recommendations",
            "data_quality_notes",
            "missing_information",
            "sources_used",
        ]

        for field in list_fields:
            if field in result and not isinstance(
                result[field], list
            ):
                errors.append(f"{field} must be an array")

        allowed_types = [
            "Milestone Inquiry",
            "Timeline Overview",
            "Schedule Risk Assessment",
            "Milestone Status Report",
            "General Milestone Report",
        ]

        if result.get("report_type") not in allowed_types:
            errors.append("Invalid report_type")

        expected_project = source.get(
            "project_name",
            "AI Adoption Project at ABCDE Ltd."
        )

        if result.get("project_name") != expected_project:
            errors.append("Project name does not match source")

        source_status = source.get("data_status")
        successful_source = source_status == "SUCCESS"

        # Source-owned metadata must not depend on LLM transcription.
        # Preserve the original type checks above: only repair a list,
        # never silently accept an incorrectly typed or missing field.
        source_notes = source.get("data_quality_notes")
        if (successful_source and isinstance(source_notes, list)
                and isinstance(result.get("data_quality_notes"), list)):
            result["data_quality_notes"] = list(source_notes)

        # Relative-time questions need a verified anchor. A planned
        # timeline alone does not identify the current project week.
        q = request.lower()
        relative_time_request = bool(re.search(
            r"\b(next\s+\d+\s+weeks?|upcoming|coming up|"
            r"this week|next month|currently overdue)\b", q
        ))
        reference_in_request = bool(re.search(
            r"\b(?:as of|starting|from)\s+(?:week\s+\d+|"
            r"\d{4}-\d{2}-\d{2})\b|"
            r"\bcurrent\s+project\s+week\s*(?:is|:)?\s*\d+\b",
            q,
        ))
        reference_in_context = any(
            source.get(key) not in (None, "", "NOT_PROVIDED")
            for key in (
                "current_project_week", "report_as_of_date",
                "reporting_date", "reference_date"
            )
        ) or bool(source.get("project_start_date") and
                  source.get("reporting_date"))
        missing_temporal_reference = (
            successful_source and relative_time_request
            and not reference_in_request and not reference_in_context
        )

        if successful_source and missing_temporal_reference:
            if result.get("status") != "INSUFFICIENT_INFORMATION":
                errors.append(
                    "Relative-time request without reference requires "
                    "INSUFFICIENT_INFORMATION"
                )
            if result.get("phases") != []:
                errors.append(
                    "Unanchored relative-time request requires phases=[]"
                )
            if result.get("schedule_risks") != []:
                errors.append(
                    "Unanchored relative-time request requires schedule_risks=[]"
                )
            if not isinstance(result.get("missing_information"), list) or not result.get("missing_information"):
                errors.append("Missing reporting reference must be explained")
            if result.get("report_scope") != "project":
                errors.append("Report scope mismatch")
            if result.get("report_type") != "Milestone Inquiry":
                errors.append("Relative-time inquiry requires Milestone Inquiry report type")
            if result.get("total_source_phases") != source.get("total_phases"):
                errors.append("Total phase count mismatch")
            if result.get("planned_project_duration_weeks") != source.get("planned_project_duration_weeks"):
                errors.append("Project duration mismatch")
            expected_notes = source.get("data_quality_notes", [])
            actual_notes = result.get("data_quality_notes", [])
            if isinstance(actual_notes, list):
                for note in expected_notes:
                    if note not in actual_notes:
                        errors.append("Missing source data quality note: " + str(note))
            expected_source = source.get("source_file")
            if result.get("sources_used") not in ([], [expected_source]):
                errors.append("sources_used does not match source")

        elif successful_source:
            if result.get("status") != "SUCCESS":
                errors.append(
                    "Valid source requires SUCCESS status"
                )

            if result.get("total_source_phases") != source.get(
                "total_phases"
            ):
                errors.append("Total phase count mismatch")

            if result.get(
                "planned_project_duration_weeks"
            ) != source.get(
                "planned_project_duration_weeks"
            ):
                errors.append("Project duration mismatch")

            scope_type = source.get("scope_type")
            phase_number = source.get("requested_phase")

            expected_scope = (
                f"Phase {phase_number}"
                if scope_type == "phase"
                else "project"
            )

            if result.get("report_scope") != expected_scope:
                errors.append("Report scope mismatch")

            expected_phases = source.get(
                "selected_phases", []
            )
            actual_phases = result.get("phases", [])

            if not isinstance(actual_phases, list):
                actual_phases = []

            if len(actual_phases) != len(expected_phases):
                errors.append(
                    "Selected phase coverage mismatch"
                )

            expected_by_id = {
                p["phase"]: p for p in expected_phases
                if isinstance(p, dict) and "phase" in p
            }

            actual_ids = []

            exact_fields = [
                "phase",
                "phase_name",
                "start_week",
                "end_week",
                "duration_weeks",
                "key_activities",
                "milestones_deliverables",
                "actual_status",
                "actual_completion_date",
                "dependencies",
            ]

            for phase in actual_phases:
                if not isinstance(phase, dict):
                    errors.append(
                        "Phase record must be an object"
                    )
                    continue

                phase_id = phase.get("phase")
                actual_ids.append(phase_id)

                expected = expected_by_id.get(phase_id)

                if expected is None:
                    errors.append(
                        f"Unexpected phase: {phase_id}"
                    )
                    continue

                for field in exact_fields:
                    if phase.get(field) != expected.get(field):
                        errors.append(
                            f"Phase {phase_id}: {field} "
                            "does not match source"
                        )

            if len(actual_ids) != len(set(
                str(x) for x in actual_ids
            )):
                errors.append("Duplicate phase records")

            if set(actual_ids) != set(expected_by_id):
                errors.append(
                    "Returned phase IDs do not match scope"
                )

            expected_source = source.get("source_file")

            if result.get("sources_used") != [
                expected_source
            ]:
                errors.append(
                    "sources_used does not match source"
                )

            required_notes = source.get(
                "data_quality_notes", []
            )
            actual_notes = result.get(
                "data_quality_notes", []
            )

            if isinstance(actual_notes, list):
                for note in required_notes:
                    if note not in actual_notes:
                        errors.append(
                            "Missing source data quality note: "
                            + str(note)
                        )

        else:
            if result.get("status") != (
                "INSUFFICIENT_INFORMATION"
            ):
                errors.append(
                    "Unavailable source must return "
                    "INSUFFICIENT_INFORMATION"
                )

            if result.get("phases") != []:
                errors.append(
                    "Unavailable source must have no phases"
                )

            if result.get("sources_used") != []:
                errors.append(
                    "Unavailable source must have no sources_used"
                )

            missing = result.get("missing_information")
            if not isinstance(missing, list) or not missing:
                errors.append(
                    "Missing information must be explained"
                )

        summary = result.get("executive_summary")

        if not isinstance(summary, str) or not summary.strip():
            errors.append("Executive summary is missing")

        # Guard against unsupported progress claims.
        if successful_source:
            text = str(summary or "").lower()

            unsupported_patterns = [
                r"\bis currently on track\b",
                r"\bis on schedule\b",
                r"\bhas been completed\b",
                r"\bhas been delayed\b",
                r"\bis overdue\b",
                r"\bcurrently delayed\b",
                r"\bcompleted successfully\b",
            ]

            if not source.get(
                "actual_completion_data_available", False
            ):
                for pattern in unsupported_patterns:
                    if re.search(pattern, text):
                        errors.append(
                            "Executive summary contains "
                            "unsupported progress claim"
                        )
                        break

        # Check that a real user request reached the validator.
        if not request.strip():
            errors.append(
                "User Request input is empty or disconnected"
            )

        output = {
            "validation_status": (
                "PASS" if not errors else "FAIL"
            ),
            "validation_errors": errors,
            "validated_data": result,
        }

        return Message(
            text=json.dumps(output, indent=2, ensure_ascii=False)
        )
